import{_ as e,o as l,c as r,a2 as t}from"./chunks/framework.CdvW4CUT.js";const q=JSON.parse('{"title":"贊助伺服","description":"關於伺服器的贊助說明與回饋。","frontmatter":{"title":"贊助伺服","description":"關於伺服器的贊助說明與回饋。"},"headers":[],"relativePath":"donate/index.md","filePath":"donate.md"}'),o={name:"donate/index.md"};function i(n,a,h,d,s,u){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="伺服器贊助" tabindex="-1">伺服器贊助 <a class="header-anchor" href="#伺服器贊助" aria-label="Permalink to &quot;伺服器贊助&quot;">​</a></h1><p><strong>各位玩家好，我們是<a href="https://www.nagiasu.xyz" target="_blank" rel="noreferrer">風平浪靜NagiAsu.xyz</a>，感謝各位玩家們，願意遊玩本伺服器，也希望大家可以繼續遊玩及支持我們，謝謝你們。</strong></p><p>伺服成立已久，最初伺服開設的想法是提供一個平台，給大家在休閒之餘玩得開心，至今我們仍秉持著該理想，提供玩家更好的遊玩與服務品質。</p><p>為了滿足此目標，在伺服器營運上，時常需要有一些資金支出，如:網路費、服務租用費、設備購買、玩家回饋、人員獎勵...，這些都會經過伺服方的專業評估，確保資金皆有最大化效益，能讓玩家有更好的遊玩品質。</p><p>如果你喜歡本伺服器，同時也願意且有能力實際支持我們，歡迎提供贊助幫忙我們，小小的幫助可以讓伺服器更好。</p><p><strong>再次感謝各位玩家們的遊玩及支持！</strong></p><h1 id="須知" tabindex="-1">🔷 須知 <a class="header-anchor" href="#須知" aria-label="Permalink to &quot;:large_blue_diamond: 須知&quot;">​</a></h1><ul><li>本伺服遵守 <strong><a href="https://www.minecraft.net/zh-hant/terms#website" target="_blank" rel="noreferrer">MINECRAFT 服務條款-商業使用準則</a></strong>，贊助後並不會獲得任何對遊戲強度或平衡有重大影響的權限或道具。</li><li>此行為為贊助行為，玩家同意以贊助的名義將款項贈與伺服器，而並非雙方買賣交易。</li><li>若玩家因違反<a href="/rule/">遊玩規範</a>，而遭伺服方解除遊玩契約，款項將無法退還；已永久解除遊玩契約的玩家，也無法利用贊助來重新讓伺服方同意提供遊玩服務。</li><li>贊助回饋可能會視情況修改，請以你贊助當下所見之回饋頁面說明為主。</li></ul><h1 id="贊助方式" tabindex="-1">💎 贊助方式 <a class="header-anchor" href="#贊助方式" aria-label="Permalink to &quot;:gem: 贊助方式&quot;">​</a></h1><h4 id="付款完成後-請主動使用客服系統與我們聯繫-來確認是否收到贊助-確保雙方的權益" tabindex="-1">付款完成後，請主動使用<a href="/discord/customer_service/">客服系統</a>與我們聯繫，來確認是否收到贊助，確保雙方的權益 <a class="header-anchor" href="#付款完成後-請主動使用客服系統與我們聯繫-來確認是否收到贊助-確保雙方的權益" aria-label="Permalink to &quot;付款完成後，請主動使用[客服系統](./discord/customer_service.md)與我們聯繫，來確認是否收到贊助，確保雙方的權益&quot;">​</a></h4><ul><li>贊助金額將會以『實際收入』來統計，超商、信用卡、跨行轉帳等手續費，需由付款方自行承擔。</li><li>若對於付款有任何不了解的地方，歡迎使用<a href="/contact/">客服系統</a>詢問!</li></ul><h3 id="超商付款-信用卡贊助-匯款" tabindex="-1"><a href="https://www.nagiasu.xyz/pay.html" target="_blank" rel="noreferrer"><strong>超商付款 / 信用卡贊助 / 匯款</strong></a> <a class="header-anchor" href="#超商付款-信用卡贊助-匯款" aria-label="Permalink to &quot;[**超商付款 / 信用卡贊助 / 匯款**](https://www.nagiasu.xyz/pay.html)&quot;">​</a></h3><ul><li><a href="https://www.nagiasu.xyz/pay.html" target="_blank" rel="noreferrer">https://www.nagiasu.xyz/pay.html</a></li><li>超商付款 <ul><li>臺灣玩家，使用超商付款</li><li>支援四大超商付款(7-11、全家、OK、萊爾富)</li><li>取得付款代碼後，至超商機台上輸入，列印出繳費單，再至櫃檯繳費</li><li>手續費 : <code>33元</code> (會附加在繳費單上)</li></ul></li><li>信用卡贊助 <ul><li>信用卡贊助(支援國內與海外信用卡)</li><li>手續費 : <code>2.8875%</code>+<code>1元</code>／筆，最低<code>6元</code></li></ul></li><li>匯款帳號 <ul><li>目前提供以下銀行戶頭 : 土地銀行、板信銀行、台灣銀行、國泰世華銀行、中國信託</li><li>若您為其他家銀行，建議使用有免費跨轉優惠的戶頭~</li><li>手續費 : <code>1.05%</code>／筆，最低<code>15元</code></li></ul></li></ul><p>(若您是想要贊助硬體設備 請直接聯繫<a href="/discord/customer_service/">客服</a>)</p><h1 id="經費用途" tabindex="-1">💲 經費用途 <a class="header-anchor" href="#經費用途" aria-label="Permalink to &quot;:heavy_dollar_sign: 經費用途&quot;">​</a></h1><h3 id="硬體設備成本" tabindex="-1">硬體設備成本 <a class="header-anchor" href="#硬體設備成本" aria-label="Permalink to &quot;硬體設備成本&quot;">​</a></h3><p>伺服的硬體設備昂貴，贊助可以彌補購買設備的支出，並加速硬體的升級，以提供更順暢的遊玩品質。</p><h3 id="伺服定期支出" tabindex="-1">伺服定期支出 <a class="header-anchor" href="#伺服定期支出" aria-label="Permalink to &quot;伺服定期支出&quot;">​</a></h3><p>伺服平時運作就會產生定期的開銷，(例如:網路費支出/VPS租金)，贊助可以用於支付此成本，並維持伺服的營運。</p><h3 id="對伺服人員的支持" tabindex="-1">對伺服人員的支持 <a class="header-anchor" href="#對伺服人員的支持" aria-label="Permalink to &quot;對伺服人員的支持&quot;">​</a></h3><p>伺服人員(包含服主)皆為無給職，希望你的支持，可以讓我們更有動力繼續為這個伺服器服務。</p><p><a href="https://docs.google.com/spreadsheets/d/e/2PACX-1vQCeAS9MbR_D_xr1mYNwnOXd33d0gHX57LKKOLdNjZ1T92u0esofWvsqcPZ1B5jDeT4L2CKQZIrLw1S/pubhtml?gid=397522036&amp;single=true" target="_blank" rel="noreferrer">伺服器收支表</a></p><h1 id="贊助回饋" tabindex="-1">💲 贊助回饋 <a class="header-anchor" href="#贊助回饋" aria-label="Permalink to &quot;:heavy_dollar_sign: 贊助回饋&quot;">​</a></h1><ul><li>本回饋可能會視情況修改，請以贊助當下你所看見的回饋說明為主。</li></ul><h2 id="贊助回饋表" tabindex="-1">贊助回饋表 <a class="header-anchor" href="#贊助回饋表" aria-label="Permalink to &quot;贊助回饋表&quot;">​</a></h2><ul><li>贊助為累積制，過往已贊助的金額會累積上去</li></ul><h4 id="_100元以上" tabindex="-1">100元以上 <a class="header-anchor" href="#_100元以上" aria-label="Permalink to &quot;100元以上&quot;">​</a></h4><ul><li>可進入『主伺服(三)、設施服(三)』遊玩。</li></ul><h4 id="_200元以上" tabindex="-1">200元以上 <a class="header-anchor" href="#_200元以上" aria-label="Permalink to &quot;200元以上&quot;">​</a></h4><ul><li>最多可邀請2位無贊助的玩家加入『主伺服(三)、設施服(三)』。</li></ul><h4 id="_300元以上" tabindex="-1">300元以上 <a class="header-anchor" href="#_300元以上" aria-label="Permalink to &quot;300元以上&quot;">​</a></h4><ul><li>可使用1個自訂名字顏色(16色)，贊助完成後自行從16色選一個顏色『<a href="https://minecraft.fandom.com/zh/wiki/%E6%A0%BC%E5%BC%8F%E5%8C%96%E4%BB%A3%E7%A0%81?variant=zh-tw" target="_blank" rel="noreferrer">Minecraft 16色</a>』</li></ul><h4 id="_500元以上" tabindex="-1">500元以上 <a class="header-anchor" href="#_500元以上" aria-label="Permalink to &quot;500元以上&quot;">​</a></h4><ul><li>可使用1個自訂名字顏色(RGB色碼)，贊助完成後自行調配一個顏色做使用『<a href="https://www.rapidtables.com/web/color/RGB_Color.html" target="_blank" rel="noreferrer">自己RGB配顏色</a>』</li><li>可擁有 <strong>7個</strong> 傳送記錄點(<code>/home</code>)</li><li>傳送冷卻降低至 <strong>10秒</strong></li></ul><h4 id="_1000元以上" tabindex="-1">1000元以上 <a class="header-anchor" href="#_1000元以上" aria-label="Permalink to &quot;1000元以上&quot;">​</a></h4><ul><li>可擁有 <strong>10個</strong> 傳送記錄點(<code>/home</code>)</li><li>傳送冷卻降低至 <strong>5秒</strong></li></ul><h4 id="_2000元以上" tabindex="-1">2000元以上 <a class="header-anchor" href="#_2000元以上" aria-label="Permalink to &quot;2000元以上&quot;">​</a></h4><ul><li>可擁有 <strong>15個</strong> 傳送記錄點(<code>/home</code>) <ul><li>2500元:17個、3000元:20個、3500元:22個、4000元:25個、4500元:27個、5000元:30個</li></ul></li><li>傳送冷卻降低至 <strong>1秒</strong></li><li>可使用2個自訂名字顏色(RGB色碼)</li><li>可獲得<strong>自訂暱稱</strong></li></ul><h3 id="回饋說明" tabindex="-1">回饋說明 <a class="header-anchor" href="#回饋說明" aria-label="Permalink to &quot;回饋說明&quot;">​</a></h3><ul><li>邀請玩家加入『主伺服(三)、設施服(三)』。 <ul><li>請先前往主三或設三，之後在遊戲內輸入指令 : <code>/wl add &lt;要邀請的玩家ID&gt;</code>，來進行白名單的設定。</li><li>設定後是無法移除的，所以請慎重選擇要增加的玩家。 <ul><li>例外情況是:若被加的玩家，因贊助獲得白名單後，將會空出邀請名額，屆時可重新進行設定。</li></ul></li></ul></li><li>名字顏色 <ul><li><a href="https://minecraft.fandom.com/zh/wiki/%E6%A0%BC%E5%BC%8F%E5%8C%96%E4%BB%A3%E7%A0%81?variant=zh-tw" target="_blank" rel="noreferrer">查看Minecraft 16色顏色代碼</a>、<a href="https://www.rapidtables.com/web/color/RGB_Color.html" target="_blank" rel="noreferrer">自己RGB配顏色</a></li><li>色碼選擇完成後，請使用<a href="/contact/">客服</a>與我們聯繫，將由伺服人員為您進行設定 <ul><li>你可以開一個單人創造，把你想要的顏色改好，打指令自己看會長什麼樣子<br><code>/tellraw @s [{&quot;text&quot;:&quot;你的ID&quot;,&quot;color&quot;:&quot;#C58181&quot;},{&quot;text&quot;:&quot; &gt; &quot;,&quot;color&quot;:&quot;gray&quot;},{&quot;text&quot;:&quot;Hello World&quot;,&quot;color&quot;:&quot;white&quot;}]</code><br> 把ID改成自己的 <code>#C58181</code>改成你想要的顏色</li></ul></li><li>伺服人員為您設定完成後，請輸入<code>/tg</code>來套用顏色，你隨時可以選擇是否要套用名字顏色。</li></ul></li><li>自訂暱稱 <ul><li>可以用來做為你的暱稱(在聊天室中取代你的名字顯示)</li><li>暱稱設定需透過<a href="/discord/customer_service/">客服</a>，請在<strong>贊助前</strong>使用<a href="/discord/customer_service/">客服</a>與我們討論，以確保您的權益。</li></ul></li><li>顏色/暱稱的試用期 <ul><li>顏色及暱稱設定完成後有72小時的試用期(從幫您設定完成後開始算起)，在試用期間，您可以自由提出是否更換目前設定的顏色或暱稱，若超過試用期，往後想要更改顏色或暱稱將酌收200元費用。</li></ul></li></ul><p>再次感謝大家的贊助與支持!</p><h2 id="聯絡伺服" tabindex="-1">聯絡伺服 <a class="header-anchor" href="#聯絡伺服" aria-label="Permalink to &quot;聯絡伺服&quot;">​</a></h2><p><a href="/discord/customer_service/">Discord 客服</a><br> Discord ID：<code>miunapa</code></p>',43)])])}const f=e(o,[["render",i]]);export{q as __pageData,f as default};
